makeCar(66,5.4,-255,false);makeCar(51,-1.8,-300,false,true);
// Driving state and interaction.
let started=false,paused=false,ended=false,clockSec=0,speed=0,steer=0,gasHeld=false,brakeHeld=false,lightOn=false,radarOn=false,lockedCar=null,lookX=0,lookY=0,lastTime=0,score=0,stops=0,dispatchDone=false,toastTimer=0,toastKey='';
const status=$('#status'), alertToast=(html,key='')=>{if(key&&toastKey===key)return;toastKey=key;status.innerHTML=html;status.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>status.classList.remove('show'),2500)};
function timeText(){let s=clockSec+7*3600+40*60;let h=Math.floor(s/3600)%24,m=Math.floor(s/60)%60,ss=Math.floor(s)%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;}
function showDispatch(){if(dispatchDone)return;dispatchDone=true;$('#dispatch').classList.remove('hidden');$('#dispatchText').textContent='Unit 214, caller reports a gray sedan weaving near milepost 38. Use your judgment.';$('#missionTitle').textContent='TRAFFIC COMPLAINT';$('#missionDesc').textContent='A weaving vehicle has been reported ahead. Confirm behavior before making a stop.';$('#objectiveText').innerHTML='Use radar to verify speed; pull alongside and <b>initiate a safe stop</b>.';alertToast('DISPATCH · Caller reports a weaving sedan near milepost 38.');}
function setRadar(){if(!radarOn){$('#radarMode').textContent='STANDBY';$('#radarMode').style.color='var(--lime)';$('#targetSpeed').textContent='--';$('#radarTarget').textContent='NO TARGET LOCKED';return;}$('#radarMode').textContent=lockedCar?'LOCKED':'SCANNING';$('#radarMode').style.color=lockedCar?'var(--gold)':'var(--lime)';$('#targetSpeed').textContent=lockedCar?String(Math.round(lockedCar.speed)):'--';$('#radarTarget').textContent=lockedCar?(lockedCar.oncoming?'ONCOMING · LANE 1':'AHEAD · LANE 2'):'SCANNING TRAFFIC';}
function toggleRadar(){radarOn=!radarOn;$('#actionBtn').classList.toggle('active',radarOn);lockedCar=null;if(radarOn){const candidates=traffic.filter(c=>!c.oncoming&&!c.done&&!c.stopped&&c.z<camera.position.z-10&&c.z>camera.position.z-150).sort((a,b)=>Math.abs(a.z-camera.position.z)-Math.abs(b.z-camera.position.z));lockedCar=candidates[0]||null;setRadar();if(lockedCar){alertToast(`RADAR LOCK · ${Math.round(lockedCar.speed)} MPH · LIMIT 55`);if(lockedCar.speed>60)score+=5;}else alertToast('Radar scanning · no vehicle in range.');}else{setRadar();alertToast('Radar returned to standby.');}}
function makeStop(){if(!started||ended)return;let target=lockedCar&&lockedCar.offender&&!lockedCar.done?lockedCar:traffic.filter(c=>c.offender&&!c.done&&!c.stopped&&c.z<camera.position.z&&c.z>camera.position.z-85).sort((a,b)=>Math.abs(a.z-camera.position.z)-Math.abs(b.z-camera.position.z))[0];if(!target){alertToast('No confirmed violator close enough. Use radar, then pull alongside.');return;}const distance=Math.abs(target.z-camera.position.z);if(distance>42||Math.abs(target.lane-camera.position.x)>7.8){alertToast('Pull alongside the vehicle before initiating a stop.');return;}if(speed>12){alertToast('Slow to a safe speed before making a traffic stop.');return;}target.stopped=true;stops++;score+=50;$('#missionTitle').textContent='TRAFFIC STOP';$('#missionDesc').textContent='The driver has pulled over safely. Keep a safe position and complete your contact.';$('#objectiveText').innerHTML='Approach with care. Document the stop and return to <b>your patrol route</b>.';$('#actionBtn').innerHTML='<span class="glyph">✓</span><b>COMPLETE</b>';$('#actionBtn').classList.add('active');$('#actionBtn').onclick=()=>{target.done=true;target.group.visible=false;score+=50;$('#actionBtn').innerHTML='<span class="glyph">◉</span><b>RADAR</b>';$('#actionBtn').classList.remove('active');$('#actionBtn').onclick=toggleRadar;$('#missionTitle').textContent='MORNING PATROL';$('#missionDesc').textContent='Traffic contact documented. Continue your patrol of the corridor.';$('#objectiveText').innerHTML='Stay alert and drive safely. <b>More traffic is ahead.</b>';alertToast('CONTACT COMPLETE · Thank you for keeping Oregon roads safe.');};alertToast('SAFE STOP INITIATED · Vehicle is pulled over.');}
function startShift(){started=true;$('#startScreen').classList.add('gone');clockSec=0;lastTime=performance.now();alertToast('SHIFT STARTED · Drive safely. Radar limit 55 MPH.');setTimeout(showDispatch,18000);}
function togglePause(){if(!started||ended)return;paused=!paused;$('#pauseScreen').classList.toggle('show',paused);if(!paused)lastTime=performance.now();gasHeld=false;}
function finishShift(){ended=true;$('#endSummary').textContent=`${stops} safe traffic stop${stops===1?'':'s'} completed · ${score} patrol points earned. Thanks for keeping the Cascade County corridor safe.`;$('#endScreen').classList.add('show');}
$('#startBtn').addEventListener('click',startShift);$('#resumeBtn').addEventListener('click',togglePause);$('#pauseBtn').addEventListener('click',togglePause);$('#againBtn').addEventListener('click',()=>location.reload());$('#actionBtn').addEventListener('click',toggleRadar);
function bindHold(id,onDown,onUp){let b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('active');onDown();});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{b.classList.remove('active');onUp();});}
bindHold('#gasBtn',()=>gasHeld=true,()=>gasHeld=false);bindHold('#brakeBtn',()=>brakeHeld=true,()=>brakeHeld=false);bindHold('#leftBtn',()=>steer=-1,()=>{if(steer===-1)steer=0});bindHold('#rightBtn',()=>steer=1,()=>{if(steer===1)steer=0});
$('#sirenBtn').addEventListener('click',()=>{lightOn=!lightOn;$('#sirenBtn').classList.toggle('active',lightOn);beaconL.intensity=lightOn?2.8:0;beaconR.intensity=lightOn?2.8:0;alertToast(lightOn?'Emergency lights on · Siren is not engaged.':'Emergency lights off.');});$('#hornBtn').addEventListener('click',()=>{alertToast('Horn sounded. Drive courteously.');});
const keyState={};addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keyState[e.key.toLowerCase()]=true;if(e.key==='Escape'||e.key.toLowerCase()==='p')togglePause();if(e.key.toLowerCase()==='r')toggleRadar();if(e.key.toLowerCase()==='e')makeStop();});addEventListener('keyup',e=>keyState[e.key.toLowerCase()]=false);
let pointerDown=false,pointerX=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button===0){pointerDown=true;pointerX=e.clientX;renderer.domElement.setPointerCapture(e.pointerId);}});renderer.domElement.addEventListener('pointermove',e=>{if(pointerDown&&started&&!paused){let dx=e.clientX-pointerX;lookX=THREE.MathUtils.clamp(lookX-dx*.0018,-.52,.52);pointerX=e.clientX;}});renderer.domElement.addEventListener('pointerup',()=>pointerDown=false);renderer.domElement.addEventListener('pointercancel',()=>pointerDown=false);

