// Rain-free, cool morning lighting with a sun angle in the Cascades.
function update(dt){if(!started||paused||ended)return;clockSec+=dt;$('#clock').textContent=timeText();if(clockSec>=480){finishShift();return;}
const wantGas=gasHeld||keyState['arrowup']||keyState['w'],wantBrake=brakeHeld||keyState['arrowdown']||keyState['s'];const steerInput=steer||(keyState['arrowleft']||keyState['a']?-1:0)||(keyState['arrowright']||keyState['d']?1:0);speed+=wantGas?dt*12:0;speed-=wantBrake?dt*26:dt*1.35;speed=THREE.MathUtils.clamp(speed,0,84);camera.position.x=THREE.MathUtils.clamp(camera.position.x+steerInput*dt*(1.9+speed*.055),-5.7,5.7);camera.rotation.y=THREE.MathUtils.damp(camera.rotation.y,lookX+steerInput*.025,3,dt);camera.rotation.x=THREE.MathUtils.damp(camera.rotation.x,lookY,3,dt);camera.position.z-=speed*.447*dt;$('#speed').textContent=Math.round(speed);
// Loop landscape pieces in front of the cruiser for an endless patrol.
