if(!car.oncoming&&!car.stopped&&car.z<camera.position.z-225){car.z=camera.position.z-420-Math.random()*130;car.speed=car.initialSpeed;car.offender=Math.random()<.30;car.group.position.z=car.z;}
if(car.oncoming&&car.z>camera.position.z+24){car.z=camera.position.z-370-Math.random()*100;car.group.position.z=car.z;}
if(Math.abs(dz)<4.2&&Math.abs(car.lane-camera.position.x)<1.9){speed=Math.max(0,speed-20);score=Math.max(0,score-20);alertToast('COLLISION AVOIDED · Leave space and slow down.','collision');}
}
if(radarOn&&lockedCar&&!lockedCar.done){$('#targetSpeed').textContent=String(Math.round(lockedCar.speed));if(lockedCar.z>camera.position.z+20){lockedCar=null;setRadar();}}
wheel.rotation.z=THREE.MathUtils.damp(wheel.rotation.z,-steerInput*.38,8,dt);if(lightOn){beaconL.intensity=2.2+(Math.sin(clockSec*12)>0?1.8:0);beaconR.intensity=2.2+(Math.sin(clockSec*12)>0?0:1.8);}
// Simple speed-limit feedback rewards measured, safe driving.
if(speed>61&&Math.floor(clockSec*4)%19===0){score=Math.max(0,score-.5);alertToast('SPEED LIMIT 55 · Reduce speed.','speed');}
}
