// Procedural traffic with visible cabins and fictional Oregon-style CAD identities.
const traffic=[]; const carPaint=['#8d413a','#687783','#d4cbb2','#506d67','#a78b63','#424d5c','#d2d7d1','#8c8a83'];
const firstNames=['Avery','Jordan','Casey','Morgan','Riley','Taylor','Cameron','Quinn','Jamie','Parker','Reese','Drew'];
const lastNames=['Miller','Bennett','Hayes','Cooper','Brooks','Reed','Foster','Morgan','Ellis','Perry','Ward','Cole'];
const vehicleTypes=[['Subaru','Outback'],['Toyota','Camry'],['Honda','CR-V'],['Ford','Escape'],['Chevrolet','Malibu'],['Volkswagen','Jetta'],['Mazda','CX-5'],['Nissan','Altima']];
const pick=a=>a[Math.floor(Math.random()*a.length)];
function makeProfile(){const [make,model]=pick(vehicleTypes),year=2014+Math.floor(Math.random()*12),letters='ABCDEFGHJKLMNPRSTUVWXYZ',digits='0123456789';let plate='';for(let i=0;i<3;i++)plate+=letters[Math.floor(Math.random()*letters.length)];plate+=' ';for(let i=0;i<3;i++)plate+=digits[Math.floor(Math.random()*digits.length)];return {plate,make,model,year,name:`${pick(firstNames)} ${pick(lastNames)}`,license:Math.random()<.9?'VALID':'VALID · NO FLAGS',registration:Math.random()<.88?'CURRENT':'EXPIRES SOON',insurance:Math.random()<.86?'VERIFIED':'NOT ON FILE'};}
function makePlate(profile,z,front=false){const c=document.createElement('canvas');c.width=320;c.height=100;const ctx=c.getContext('2d');ctx.fillStyle='#efe7c8';ctx.fillRect(0,0,320,100);ctx.strokeStyle='#31534b';ctx.lineWidth=7;ctx.strokeRect(4,4,312,92);ctx.fillStyle='#31534b';ctx.font='bold 22px Arial';ctx.textAlign='center';ctx.fillText('OREGON',160,27);ctx.font='bold 43px Arial';ctx.fillText(profile.plate,160,75);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;const plate=new THREE.Mesh(new THREE.PlaneGeometry(.58,.18),new THREE.MeshBasicMaterial({map:texture}));plate.position.set(0,.59,z);if(front)plate.rotation.y=Math.PI;return plate;}
function makeCar(speed,lane,z,offender=false,oncoming=false){const g=new THREE.Group(),paint=mat(carPaint[Math.floor(Math.random()*carPaint.length)],.3,.16);g.position.set(lane,.02,z);scene.add(g);g.rotation.y=oncoming?Math.PI:0;
 box(g,1.72,.66,4.0,paint,0,.68,0);box(g,1.43,.57,1.85,mats.glass,0,1.17,-.12);box(g,1.4,.15,1.08,paint,0,1.05,-1.05);box(g,1.38,.14,.95,paint,0,1.05,.94);box(g,1.37,.07,1.77,paint,0,1.51,-.1);
 // Dashboard, front seats, headrests, rear bench, and steering wheel are visible through glass.
 box(g,1.24,.12,.43,mat('#20282a'),0,.97,-.78);box(g,1.12,.12,.7,mat('#272d2e'),0,.91,.47);
 for(const x of [-.43,.43]){box(g,.43,.48,.43,mat('#303536'),x,1.12,-.12);box(g,.43,.16,.17,mat('#3b4241'),x,1.43,-.32);box(g,.43,.35,.4,mat('#303536'),x,1.05,.62);}
 const steering=new THREE.Mesh(new THREE.TorusGeometry(.18,.025,8,20),mat('#171c1d'));steering.position.set(-.42,1.13,-.57);steering.rotation.x=.1;g.add(steering);box(g,.44,.08,.12,mat('#171c1d'),0,1.01,-.78);
 // Window pillars and side glass highlights add readable sedan/SUV silhouettes.
 for(const x of [-.69,.69])for(const zz of [-.88,.65])box(g,.055,.55,.07,mat('#303839'),x,1.18,zz);
 for(const x of [-.62,.62]){const light=new THREE.Mesh(new THREE.BoxGeometry(.3,.18,.05),oncoming?mat('#f6e8bd',.25):mat('#ed493d',.25));light.position.set(x,.65,oncoming?-2.02:2.02);g.add(light);}
 const profile=makeProfile(),plateZ=oncoming?-2.045:2.045;g.add(makePlate(profile,plateZ,oncoming));
 for(const x of [-.89,.89])for(const zz of [-1.25,1.25]){let tire=new THREE.Mesh(new THREE.CylinderGeometry(.34,.34,.19,12),mats.tire);tire.rotation.z=Math.PI/2;tire.position.set(x,.35,zz);tire.castShadow=true;g.add(tire);}
 const id=traffic.length;const car={group:g,speed,lane,z,offender,oncoming,initialSpeed:speed,stopped:false,done:false,id,profile};traffic.push(car);return car;}
makeCar(69,1.8,-108,true);makeCar(61,5.4,-173,true);makeCar(53,1.8,-215,false);makeCar(58,5.4,-82,false);makeCar(64,-1.8,-130,false,true);makeCar(58,-5.4,-235,false,true);makeCar(66,5.4,-255,false);makeCar(51,-1.8,-300,false,true);

